INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-gimi-1', 'sent-ex-gimi-1', 'en', 'I feel a bit of a cold coming on today.', 'authored'),
  ('st-ex-gimi-2', 'sent-ex-gimi-2', 'en', 'I have been a little tired lately.', 'authored'),
  ('st-ex-gimi-3', 'sent-ex-gimi-3', 'en', 'I am putting on a bit of weight.', 'authored'),
  ('st-ex-gimi-4', 'sent-ex-gimi-4', 'en', 'The trains are running slightly late.', 'authored'),
  ('st-ex-kake-1', 'sent-ex-kake-1', 'en', 'I have a book I am partway through.', 'authored'),
  ('st-ex-kake-2', 'sent-ex-kake-2', 'en', 'There is a half-eaten cake on the desk.', 'authored'),
  ('st-ex-kake-3', 'sent-ex-kake-3', 'en', 'I started to say it and stopped.', 'authored'),
  ('st-ex-kake-4', 'sent-ex-kake-4', 'en', 'There is a half-made dish.', 'authored'),
  ('st-ex-gatai-1', 'sent-ex-gatai-1', 'en', 'It is a hard story to believe.', 'authored'),
  ('st-ex-gatai-2', 'sent-ex-gatai-2', 'en', 'It is a memory I find hard to forget.', 'authored'),
  ('st-ex-gatai-3', 'sent-ex-gatai-3', 'en', 'It is a fact that cannot be shifted.', 'authored'),
  ('st-ex-gatai-4', 'sent-ex-gatai-4', 'en', 'It is unforgivable behaviour.', 'authored'),
  ('st-ex-youganai-1', 'sent-ex-youganai-1', 'en', 'There is no way of getting in touch.', 'authored'),
  ('st-ex-youganai-2', 'sent-ex-youganai-2', 'en', 'It is broken and there is no way of fixing it.', 'authored'),
  ('st-ex-youganai-3', 'sent-ex-youganai-3', 'en', 'There is no way to answer that.', 'authored'),
  ('st-ex-youganai-4', 'sent-ex-youganai-4', 'en', 'From here there is no way of making it in time.', 'authored'),
  ('st-ex-tsutsu-1', 'sent-ex-tsutsu-1', 'en', 'Knowing it was wrong, I carried on all the same.', 'authored'),
  ('st-ex-tsutsu-2', 'sent-ex-tsutsu-2', 'en', 'I study while listening to music.', 'authored'),
  ('st-ex-tsutsu-3', 'sent-ex-tsutsu-3', 'en', 'The town is in the middle of changing.', 'authored'),
  ('st-ex-tsutsu-4', 'sent-ex-tsutsu-4', 'en', 'My body is on the mend.', 'authored'),
  ('st-ex-nagaramo-1', 'sent-ex-nagaramo-1', 'en', 'Small though it is, it is a well-known shop.', 'authored'),
  ('st-ex-nagaramo-2', 'sent-ex-nagaramo-2', 'en', 'Even though he knew, he said nothing.', 'authored'),
  ('st-ex-nagaramo-3', 'sent-ex-nagaramo-3', 'en', 'Poor though they were, they were happy.', 'authored'),
  ('st-ex-nagaramo-4', 'sent-ex-nagaramo-4', 'en', 'Young as he is, he works hard.', 'authored'),
  ('st-ex-monono-1', 'sent-ex-monono-1', 'en', 'I promised, and yet I could not go.', 'authored'),
  ('st-ex-monono-2', 'sent-ex-monono-2', 'en', 'I bought it, and yet I have not used it.', 'authored'),
  ('st-ex-monono-3', 'sent-ex-monono-3', 'en', 'It is difficult, but interesting all the same.', 'authored'),
  ('st-ex-monono-4', 'sent-ex-monono-4', 'en', 'I sat the exam, but I failed it.', 'authored'),
  ('st-ex-kuseni-1', 'sent-ex-kuseni-1', 'en', 'He knows perfectly well, and still will not tell me.', 'authored'),
  ('st-ex-kuseni-2', 'sent-ex-kuseni-2', 'en', 'He is only a child and yet he uses difficult words.', 'authored'),
  ('st-ex-kuseni-3', 'sent-ex-kuseni-3', 'en', 'He is no good at it and still sings all the time.', 'authored'),
  ('st-ex-kuseni-4', 'sent-ex-kuseni-4', 'en', 'He has the money and yet he will not pay.', 'authored'),
  ('st-ex-seide-1', 'sent-ex-seide-1', 'en', 'The match was called off because of the rain.', 'authored'),
  ('st-ex-seide-2', 'sent-ex-seide-2', 'en', 'I was off school because of a cold.', 'authored'),
  ('st-ex-seide-3', 'sent-ex-seide-3', 'en', 'The train was late, and because of that I was late in.', 'authored'),
  ('st-ex-seide-4', 'sent-ex-seide-4', 'en', 'It went wrong because of him.', 'authored'),
  ('st-ex-okagede-1', 'sent-ex-okagede-1', 'en', 'Thanks to the teacher I passed.', 'authored'),
  ('st-ex-okagede-2', 'sent-ex-okagede-2', 'en', 'Thanks to the medicine I got better.', 'authored'),
  ('st-ex-okagede-3', 'sent-ex-okagede-3', 'en', 'Thanks to him I was saved.', 'authored'),
  ('st-ex-okagede-4', 'sent-ex-okagede-4', 'en', 'Thanks to the good weather it turned into an enjoyable trip.', 'authored')
